"""TLE implementation of ``_conj_copy`` for Ascend.

``_conj_copy`` returns a fresh, physically resolved conjugate copy.  A complex
tensor is stored as interleaved (real, imaginary) float pairs, and conjugation
only flips the sign bit of the imaginary half.  The kernel therefore works on
the raw *word* payload and XORs that bit into the imaginary lanes: no
reduction, no accumulation, no cross-lane interaction.

The XOR form is deliberate.  Negating a float payload lowers to a float
broadcast, and BiSheng rejects ``hivm.hir.vbrc`` for 64-bit floats, so a
``complex128`` tensor would not compile with ``-x``.  It is also why the
payload is addressed as ``int32`` words even for ``complex128``: the sign bit
of a float64 sits in the high word of the pair (word index ``i % 4 == 3``),
while native ``int64`` transfers are emulated on this stack and were measured
to misplace bits.  32-bit words keep every transfer native and bit-exact.

Tile choice is deterministic host dispatch rather than a per-call autotuner.
The kernel is bandwidth bound above ~64K elements, where the widest tile wins,
and latency / occupancy bound below it, where a wide tile starves the grid; a
per-call autotuner measurably cost the medium regime more than it gained.

The clamped full-tile paths deliberately overlap the tail: ``base`` is clamped
so every program owns a complete in-bounds tile, and the benign overlap
rewrites identical bytes because the input is never modified.
"""

import logging

import torch
import torch_npu  # noqa: F401  # must precede triton on this platform

import triton
import triton.experimental.tle as tle
import triton.language as tl

logger = logging.getLogger(__name__)


@triton.jit
def _conj_copy_clamped_kernel(
    src_ptr,
    dst_ptr,
    n_elements,
    SIGN: tl.constexpr,
    MASK: tl.constexpr,
    REM: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Full-tile, unmasked path with a DSA-staged store.

    Only launched when ``n_elements >= BLOCK``.
    """
    pid = tl.program_id(0)
    # n_elements is even (2 * numel) and BLOCK is a power of two >= 2, so the
    # clamped base is always even and parity of (base + i) equals parity of i.
    base = tl.minimum(pid * BLOCK, n_elements - BLOCK)
    lane = tl.arange(0, BLOCK)
    offs = base + lane
    x = tl.load(src_ptr + offs)
    # Bitwise parity instead of `lane % 2`: the modulo lowers to arith.remsi,
    # which BiSheng expands into a serial per-lane scalar loop, a fixed
    # ~100 us per launch on every shape.  Bitwise AND is a native vector op.
    sign = tl.full(x.shape, SIGN, x.dtype)
    y = tl.where((lane & MASK) == REM, x ^ sign, x)
    y_ub = tle.dsa.to_buffer(y, space=tle.dsa.ascend.UB)
    tle.dsa.copy(y_ub, dst_ptr + offs, [BLOCK])


@triton.jit
def _conj_copy_clamped_store_kernel(
    src_ptr,
    dst_ptr,
    n_elements,
    SIGN: tl.constexpr,
    MASK: tl.constexpr,
    REM: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Latency-bound variant of the clamped tile: no explicit DSA staging.

    The narrow tier measured this body at its best recorded latency, so the
    direct store stays; the remaining cost there is per-block prologue, so the
    ceiling is ``BLOCK == n_elements`` (a single program) rather than tile width.
    """
    pid = tl.program_id(0)
    base = tl.minimum(pid * BLOCK, n_elements - BLOCK)
    lane = tl.arange(0, BLOCK)
    offs = base + lane
    x = tl.load(src_ptr + offs)
    sign = tl.full(x.shape, SIGN, x.dtype)
    y = tl.where((lane & MASK) == REM, x ^ sign, x)
    tl.store(dst_ptr + offs, y)


